window.clientAdminModal=id=>{const c=id?(state.clients||[]).find(x=>x.id===id):{};modal(id?'Edit client':'Add client',`<form id="admin-client-form" class="form-grid"><div class="field"><label>Account type</label><select class="select" name="accountType"><option value="OWNER" ${c?.account_type!=='PROPERTY_MANAGER'?'selected':''}>OWNER</option><option value="PROPERTY_MANAGER" ${c?.account_type==='PROPERTY_MANAGER'?'selected':''}>PROPERTY_MANAGER</option></select></div><div class="field"><label>Language</label><select class="select" name="language">${ST_I18N.LANGS.map(l=>`<option value="${l}" ${String(c?.language||'ru')===l?'selected':''}>${ST_I18N.NAMES[l]}</option>`).join('')}</select></div><div class="field"><label>Full name</label><input class="input" name="fullName" required value="${esc(c?.full_name||'')}"></div><div class="field"><label>Company name</label><input class="input" name="companyName" value="${esc(c?.company_name||'')}"></div><div class="field"><label>Email</label><input class="input" type="email" name="email" required value="${esc(c?.email||'')}"></div><div class="field"><label>Phone</label><input class="input" name="phone" value="${esc(c?.phone||'')}"></div>${id?'':`<div class="field wide"><label>Initial password</label><input class="input" type="password" name="password" minlength="10" required placeholder="Temporary password (10+ chars)"></div>`}<div class="field"><label>Billing name</label><input class="input" name="billingName" value="${esc(c?.billing_name||'')}"></div><div class="field"><label>ICO</label><input class="input" name="ico" value="${esc(c?.ico||'')}"></div><div class="field"><label>DIC</label><input class="input" name="dic" value="${esc(c?.dic||'')}"></div><div class="field"><label>IC DPH</label><input class="input" name="icDph" value="${esc(c?.ic_dph||'')}"></div><div class="field wide"><label>Billing address</label><input class="input" name="billingAddress" value="${esc(c?.billing_address||'')}"></div>${id?`<div class="field"><label>State</label><select class="select" name="active"><option value="true" ${c.user_active?'selected':''}>Active</option><option value="false" ${!c.user_active?'selected':''}>Inactive</option></select></div>`:''}</form>`,`${id?`<button class="btn orange" onclick="resetClientPassword(${id})">Reset password</button>`:''}<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveAdminClient(${id||0})">Save</button>`)};
