async function adminFinance(month=(new Date()).toISOString().slice(0,7)){shellTitle('Finance','Monthly revenue, cleaner costs and contribution profit');const d=await api(`/api/admin/finance?month=${encodeURIComponent(month)}`);state.finance=d;const s=d.summary,max=Math.max(1,...d.trend.map(x=>Math.max(Number(x.revenue),Number(x.expenses))));$('#page').innerHTML=`<div class="section-head"><div><h2>Finance overview</h2><p>${fmtDate(d.from)} — ${fmtDate(d.to)} · ${s.completedJobs} completed jobs</p></div><div style="display:flex;gap:8px;align-items:center"><input id="finance-month" class="input" style="width:165px" type="month" value="${d.month}" onchange="setFinancePeriod(this.value)"><button class="btn primary" onclick="financeEntryModal()">+ Add entry</button></div></div><div class="grid finance-kpis"><div class="card kpi"><div class="label">Revenue</div><div class="value small-money">${money(s.totalRevenue)}</div><div class="hint">cleaning ${money(s.cleaningRevenue)} + other ${money(s.manualIncome)}</div></div><div class="card kpi"><div class="label">Cleaner payouts</div><div class="value small-money">${money(s.cleanerPayouts+s.cleanerBonuses)}</div><div class="hint">base ${money(s.cleanerPayouts)} + bonuses ${money(s.cleanerBonuses)}</div></div><div class="card kpi"><div class="label">Expenses</div><div class="value small-money">${money(s.totalExpenses)}</div><div class="hint">job extras ${money(s.jobExtraCosts)} + other ${money(s.manualExpenses)}</div></div><div class="card kpi ${s.profit<0?'danger':''}"><div class="label">Profit</div><div class="value small-money ${s.profit>=0?'profit-pos':'profit-neg'}">${money(s.profit)}</div><div class="hint">${s.marginPct}% Margin</div></div><div class="card kpi"><div class="label">Average revenue / job</div><div class="value small-money">${money(s.avgRevenuePerJob)}</div></div><div class="card kpi"><div class="label">Average profit / job</div><div class="value small-money">${money(s.avgProfitPerJob)}</div></div></div><div style="height:14px"></div><div class="card pad"><div class="section-head compact"><div><h2>12 month trend</h2><p>Revenue / expenses / contribution profit</p></div></div><div class="finance-trend">${d.trend.map(x=>`<div class="trend-col"><div class="trend-bars"><span class="trend-revenue" title="Revenue ${money(x.revenue)}" style="height:${Math.max(3,Number(x.revenue)/max*100)}%"></span><span class="trend-expense" title="Expenses ${money(x.expenses)}" style="height:${Math.max(3,Number(x.expenses)/max*100)}%"></span></div><strong>${x.month.slice(5)}</strong><small class="${Number(x.profit)>=0?'profit-pos':'profit-neg'}">${money(x.profit)}</small></div>`).join('')}</div></div><div style="height:14px"></div><div class="two-col"><div class="card pad"><h2 style="margin-top:0">By client</h2><div class="table-wrap"><table><thead><tr><th>Client</th><th>Jobs</th><th>Revenue</th><th>Expenses</th><th>Profit</th></tr></thead><tbody>${d.byClient.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${x.jobs}</td><td>${money(x.revenue)}</td><td>${money(x.cost)}</td><td class="${x.profit>=0?'profit-pos':'profit-neg'}"><strong>${money(x.profit)}</strong></td></tr>`).join('')||'<tr><td colspan="5">—</td></tr>'}</tbody></table></div></div><div class="card pad"><h2 style="margin-top:0">By object</h2><div class="table-wrap"><table><thead><tr><th>Object</th><th>Jobs</th><th>Revenue</th><th>Expenses</th><th>Profit</th></tr></thead><tbody>${d.byObject.slice(0,20).map(x=>`<tr><td><strong>${esc(x.code)}</strong><br><span class="subtle">${esc(x.name)}</span></td><td>${x.jobs}</td><td>${money(x.revenue)}</td><td>${money(x.cost)}</td><td class="${x.profit>=0?'profit-pos':'profit-neg'}"><strong>${money(x.profit)}</strong></td></tr>`).join('')||'<tr><td colspan="5">—</td></tr>'}</tbody></table></div></div></div><div style="height:14px"></div><div class="card"><div class="section-head pad compact"><div><h2>Manual entries</h2><p>${d.entries.length} entries</p><div class="toolbar">${state.financeCursor?'<button class="btn sm" onclick="financePage(null)">First page</button>':''}${d.entriesHasMore?`<button class="btn sm" onclick="financePage(${Number(d.entriesNextCursor)})">Next page</button>`:''}</div></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Type</th><th>Category</th><th>Description</th><th>Client</th><th>Object</th><th>Amount</th><th></th></tr></thead><tbody>${d.entries.map(e=>`<tr><td>${fmtDate(e.entry_date)}</td><td><span class="pill ${e.entry_type==='INCOME'?'green':'red'}">${e.entry_type==='INCOME'?'Income':'Expense'}</span></td><td>${esc(e.category)}</td><td>${esc(e.description||'—')}</td><td>${esc(e.company_name||e.client_name||'—')}</td><td>${esc(e.object_code||'—')}</td><td class="${e.entry_type==='INCOME'?'profit-pos':'profit-neg'}"><strong>${e.entry_type==='INCOME'?'+':'−'}${money(e.amount)}</strong></td><td><button class="btn sm red" onclick="deleteFinanceEntry(${e.id})">Delete</button></td></tr>`).join('')||'<tr><td colspan="8"><div class="empty">No entries.</div></td></tr>'}</tbody></table></div></div>`}
window.adminFinance=adminFinance;
window.financeEntryModal=async()=>{try{const [c,o]=await Promise.all([api('/api/admin/clients'),api('/api/admin/objects')]);modal('Add finance entry',`<form id="finance-entry-form" class="form-grid"><div class="field"><label>Date</label><input class="input" type="date" name="entryDate" value="${today()}" required></div><div class="field"><label>Type</label><select class="select" name="entryType"><option value="EXPENSE">Expense</option><option value="INCOME">Income</option></select></div><div class="field"><label>Category</label><select class="select" name="category">${['LAUNDRY','SUPPLIES','MAINTENANCE','PARKING','REFUND','EXTRA_SERVICE','OTHER'].map(x=>`<option value="${x}">${x}</option>`).join('')}</select></div><div class="field"><label>Amount €</label><input class="input" type="number" min="0.01" step="0.01" name="amount" required></div><div class="field"><label>Client</label><select class="select" name="clientId"><option value="">—</option>${c.clients.map(x=>`<option value="${x.id}">${esc(x.company_name||x.full_name)}</option>`).join('')}</select></div><div class="field"><label>Object</label><select class="select" name="objectId"><option value="">—</option>${o.objects.map(x=>`<option value="${x.id}">${esc(x.code)} · ${esc(x.name)}</option>`).join('')}</select></div><div class="field wide"><label>Description</label><input class="input" name="description"></div></form>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveFinanceEntry()">Save</button>`)}catch(e){toast(e.message,'error')}};
