async function adminIssues(){shellTitle('Issues','Operational exceptions and resolution queue');const d=await api('/api/admin/issues');$('#page').innerHTML=`<div class="section-head"><div><h2>Issue queue</h2><p>${d.issues.filter(x=>x.status==='OPEN').length} open</p></div></div><div class="card"><div class="table-wrap"><table><thead><tr><th>Priority</th><th>Object</th><th>Type</th><th>Cleaner</th><th>Description</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody>${d.issues.map(i=>`<tr><td>${i.priority==='HIGH'?'<span class="pill red">HIGH</span>':'<span class="pill gray">NORMAL</span>'}</td><td><strong>${esc(i.object_code)}</strong></td><td>${esc(i.type)}</td><td>${esc(i.cleaner_name||'—')}</td><td>${esc(i.description||'—')}</td><td>${i.status==='OPEN'?'<span class="pill orange">OPEN</span>':'<span class="pill green">RESOLVED</span>'}</td><td>${fmtStamp(i.created_at)}</td><td>${i.status==='OPEN'?`<button class="btn green sm" onclick="resolveIssue(${i.id})">Resolve</button>`:''}</td></tr>`).join('')||'<tr><td colspan="8"><div class="empty">No issues.</div></td></tr>'}</tbody></table></div></div>`}
window.resolveIssue=async id=>{const note=prompt('Resolution note:','Resolved by operations');if(note===null)return;try{await api(`/api/admin/issues/${id}`,{method:'PATCH',body:{status:'RESOLVED',resolutionNote:note}});toast('Issue resolved','success');render()}catch(e){toast(e.message,'error')}};

async function adminTomorrow(){shellTitle('Tomorrow','Capacity reserve and pre-publishing');const date=tomorrow(),d=await api(`/api/admin/capacity?date=${date}`);$('#page').innerHTML=`<div class="section-head"><div><h2>${fmtDate(date)}</h2><p>Pre-plan demand before cleaners start choosing jobs.</p></div><button class="btn primary" onclick="generateJobsModal()">Generate tomorrow jobs</button></div><div class="grid kpis" style="grid-template-columns:repeat(5,1fr)"><div class="card kpi"><div class="label">Planned cleanings</div><div class="value">${d.jobs.length}</div></div><div class="card kpi"><div class="label">Available cleaners</div><div class="value">${d.capacity.cleaners}</div></div><div class="card kpi"><div class="label">Demand hours</div><div class="value">${(d.capacity.demandMinutes/60).toFixed(1)}</div></div><div class="card kpi"><div class="label">Capacity hours</div><div class="value">${(d.capacity.capacityMinutes/60).toFixed(1)}</div></div><div class="card kpi ${d.capacity.health==='RED'?'danger':d.capacity.health==='ORANGE'?'warn':''}"><div class="label">Reserve</div><div class="value">${d.capacity.reservePct}%</div><div class="hint">target ≥ ${state.settings.reserveTargetPct}%</div></div></div><div style="height:14px"></div><div class="two-col"><div class="card pad"><h2 style="margin-top:0">Tomorrow jobs</h2>${jobsTable(d.jobs)}</div><div class="card pad"><h2 style="margin-top:0">Cleaner availability</h2>${d.cleaners.map(c=>`<div class="risk-row"><div class="avatar">${initials(c.full_name)}</div><div><strong>${esc(c.full_name)}</strong><small>${c.mode} · ${c.available?'online/available':'not declared'} · ${c.availability.fromTime}–${c.availability.toTime}</small></div><span class="pill ${c.available?'green':'gray'}">${c.available?'Available':'Unknown'}</span></div>`).join('')||'<div class="empty">No availability for tomorrow yet.</div>'}</div></div>`}

async function adminAnalytics(){shellTitle('Analytics','Operational quality, SLA and reliability');const d=await api(`/api/admin/analytics?from=2020-01-01&to=${today()}`);$('#page').innerHTML=`<div class="grid kpis" style="grid-template-columns:repeat(5,1fr)"><div class="card kpi"><div class="label">All jobs</div><div class="value">${d.summary.jobs}</div></div><div class="card kpi"><div class="label">Completed</div><div class="value">${d.summary.completed}</div></div><div class="card kpi"><div class="label">On-time</div><div class="value">${d.summary.onTimePct}%</div></div><div class="card kpi"><div class="label">Rescue</div><div class="value">${d.summary.rescue}</div></div><div class="card kpi"><div class="label">Issues</div><div class="value">${d.summary.issues}</div></div></div><div style="height:14px"></div><div class="two-col"><div class="card pad"><h2 style="margin-top:0">Cleaner reliability</h2><div class="table-wrap"><table><thead><tr><th>Cleaner</th><th>Reliability</th><th>Rating</th><th>Completed</th><th>Reclean</th><th>Cancel</th><th>Delay</th></tr></thead><tbody>${d.cleanerRanking.map(c=>`<tr><td><strong>${esc(c.full_name)}</strong></td><td>${Math.round(c.reliability_score)}</td><td>★${c.rating}</td><td>${c.completed_jobs}</td><td>${Number(c.reclean_rate).toFixed(1)}%</td><td>${Number(c.cancellation_rate).toFixed(1)}%</td><td>${Number(c.avg_delay_minutes).toFixed(1)} min</td></tr>`).join('')}</tbody></table></div></div><div class="card pad"><h2 style="margin-top:0">Object standards</h2>${d.objectPerformance.slice(0,10).map(o=>`<div class="risk-row"><div class="risk-score" style="background:#eef1f5;color:#445065">${o.jobs}</div><div><strong>${esc(o.code)} · ${esc(o.name)}</strong><small>Standard ${o.duration_minutes} min · current avg ${o.avg_duration||'—'} min</small></div></div>`).join('')}</div></div>`}

async function adminSettings(){shellTitle('Settings','Operational rules controlling dispatch and SLA');const s=(await api('/api/admin/settings')).settings;$('#page').innerHTML=`<div class="card pad" style="max-width:850px"><form id="settings-form" class="form-grid"><div class="field"><label>Company</label><input class="input" name="companyName" value="${esc(s.companyName)}"></div><div class="field"><label>Timezone</label><input class="input" name="timezone" value="${esc(s.timezone)}" disabled></div><div class="field"><label>Window start</label><input class="input" name="windowStart" type="time" value="${s.windowStart}"></div><div class="field"><label>Hard deadline</label><input class="input" name="windowEnd" type="time" value="${s.windowEnd}"></div><div class="field"><label>Default travel buffer (min)</label><input class="input" name="travelBuffer" type="number" value="${s.travelBuffer}"></div><div class="field"><label>Same-zone travel (min)</label><input class="input" name="sameZoneTravelBuffer" type="number" value="${s.sameZoneTravelBuffer}"></div><div class="field"><label>Safety buffer / job (min)</label><input class="input" name="safetyBuffer" type="number" value="${s.safetyBuffer}"></div><div class="field"><label>Rescue starts</label><input class="input" name="rescueStart" type="time" value="${s.rescueStart}"></div><div class="field"><label>Check-in radius (m)</label><input class="input" name="checkinRadiusMeters" type="number" value="${s.checkinRadiusMeters}"></div><div class="field"><label>Reserve target %</label><input class="input" name="reserveTargetPct" type="number" value="${s.reserveTargetPct}"></div><div class="field"><label>Client booking step (min)</label><input class="input" name="clientBookingStepMinutes" type="number" min="15" step="15" value="${s.clientBookingStepMinutes??30}"></div><div class="field"><label>Client cancellation cutoff (hours)</label><input class="input" name="clientCancellationCutoffHours" type="number" min="0" value="${s.clientCancellationCutoffHours??12}"></div><div class="wide"><button class="btn primary" type="button" onclick="saveSettings()">Save settings</button></div></form><div style="height:18px"></div><div style="border-top:1px solid var(--line);padding-top:16px"><strong>Account security</strong><p class="subtle">Change the password for this administrator account.</p><button class="btn" type="button" onclick="passwordModal()">Change password</button></div></div>`}
window.saveSettings=async()=>{const f=new FormData($('#settings-form'));const body={companyName:f.get('companyName'),windowStart:f.get('windowStart'),windowEnd:f.get('windowEnd'),travelBuffer:Number(f.get('travelBuffer')),sameZoneTravelBuffer:Number(f.get('sameZoneTravelBuffer')),safetyBuffer:Number(f.get('safetyBuffer')),rescueStart:f.get('rescueStart'),checkinRadiusMeters:Number(f.get('checkinRadiusMeters')),reserveTargetPct:Number(f.get('reserveTargetPct')),clientBookingStepMinutes:Number(f.get('clientBookingStepMinutes')),clientCancellationCutoffHours:Number(f.get('clientCancellationCutoffHours'))};try{const d=await api('/api/admin/settings',{method:'PATCH',body});state.settings=d.settings;toast('Settings saved','success')}catch(e){toast(e.message,'error')}};

async function adminMap(){shellTitle('Operations Map','All objects and today jobs by operational status');const [d,objectsData]=await Promise.all([api('/api/admin/dashboard'),api('/api/admin/objects')]);const points=window.ShineTimeUi.mapPoints(objectsData.objects,d.jobs);$('#page').innerHTML='<div class="card pad"><div id="admin-map" class="map"></div></div><div style="height:14px"></div>'+jobsTable(d.jobs);setTimeout(()=>renderLeaflet('admin-map',points,p=>p.job?openAdminJob(p.id):navTo('admin/objects')),20)}
let leafletPromise=null;function loadLeaflet(){if(window.L)return Promise.resolve(true);if(leafletPromise)return leafletPromise;leafletPromise=new Promise(resolve=>{if(!document.querySelector('link[data-leaflet]')){const css=document.createElement('link');css.rel='stylesheet';css.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';css.dataset.leaflet='1';document.head.appendChild(css)}const script=document.createElement('script');script.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';script.dataset.leaflet='1';let done=false;const finish=ok=>{if(done)return;done=true;resolve(ok&&!!window.L)};script.onload=()=>finish(true);script.onerror=()=>finish(false);document.head.appendChild(script);setTimeout(()=>finish(false),3500)});return leafletPromise}async function renderLeaflet(id,points,onClick){const el=document.getElementById(id);if(!el)return;const ok=await loadLeaflet();if(!ok||!window.L){el.innerHTML=`<div class="pin-fallback" style="padding:12px">${points.map(p=>`<div class="map-list-card"><strong>${esc(p.name)}</strong><small>${esc(p.detail)}</small></div>`).join('')}</div>`;return}if(!document.getElementById(id))return;state.map=L.map(id).setView([48.1486,17.1077],12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(state.map);const bounds=[];points.filter(p=>Number.isFinite(Number(p.lat))&&Number.isFinite(Number(p.lng))).forEach(p=>{const marker=L.marker([Number(p.lat),Number(p.lng)]).addTo(state.map).bindPopup(`<strong>${esc(p.name)}</strong><br>${esc(p.detail||'')}`);if(onClick)marker.on('click',()=>setTimeout(()=>onClick(p),150));bounds.push([Number(p.lat),Number(p.lng)])});if(bounds.length===1)state.map.setView(bounds[0],15);else if(bounds.length>1)state.map.fitBounds(bounds,{padding:[28,28]})}

async function renderCleaner(page){if(page==='home')return cleanerHome();if(page==='jobs')return cleanerJobs();if(page==='map')return cleanerMap();if(page==='myday')return cleanerMyDay();if(page==='earnings')return cleanerEarnings();if(page==='profile')return cleanerProfile();return cleanerHome()}
async function cleanerHeaderAvailability(date=today()){const d=await api(`/api/cleaner/dashboard?date=${date}`);const b=$('#online-toggle');if(b){b.textContent=d.availability.online?'● ONLINE':'○ OFFLINE';b.classList.toggle('on',d.availability.online);b.onclick=()=>toggleOnline(!d.availability.online,d.availability,date)}return d}
async function toggleOnline(online,av,date=today()){try{await api('/api/cleaner/availability',{method:'PATCH',body:{date,online,fromTime:av?.fromTime||'10:00',toTime:av?.toTime||'15:00'}});toast(online?'You are online':'You are offline','success');render()}catch(e){toast(e.message,'error')}}

async function cleanerHome(){const d=await cleanerHeaderAvailability();const active=d.nextJob;$('#page').innerHTML=`<div class="mobile-kpis"><div class="mobile-kpi"><div class="v">${d.total}</div><div class="k">TODAY JOBS</div></div><div class="mobile-kpi"><div class="v">${money(d.earnings)}</div><div class="k">EARNED</div></div><div class="mobile-kpi"><div class="v">${esc(d.projectedFinish)}</div><div class="k">PROJECTED FINISH</div></div></div>${active?`<div class="next-job"><div class="eyebrow">Next cleaning</div><div style="display:flex;justify-content:space-between;gap:10px"><div><h3>${esc(active.object_code)} · ${esc(active.object_name)}</h3><div class="address">${esc(active.address)}</div></div>${statusPill(active.status)}</div><div class="job-meta"><span class="meta-chip">◷ ${active.duration_minutes} min</span><span class="meta-chip">⌖ ${esc(active.zone)}</span><span class="meta-chip">${money(Number(active.payout)+Number(active.bonus))}</span><span class="meta-chip">ETA ${esc(active.projected_finish||active.eta||'—')}</span></div><button class="btn primary full" onclick="navTo('cleaner/job/${active.id}')">Open cleaning</button></div>`:`<div class="next-job"><div class="eyebrow">You're clear</div><h3>No assigned cleaning right now</h3><p class="subtle">Choose work from the marketplace. Choose work that fits your availability and each property’s service window.</p><button class="btn primary full" onclick="navTo('cleaner/jobs')">Browse jobs</button></div>`}<div class="section-head" style="margin-top:18px"><div><h2>Your day</h2><p>${d.availability.fromTime}–${d.availability.toTime}</p></div><button class="btn sm" onclick="editAvailability('${d.availability.fromTime}','${d.availability.toTime}',${d.availability.online})">Availability</button></div>${miniDay(d.jobs)}`}
window.editAvailability=(from,to,online,date=today())=>modal(`${date===today()?'Today':'Tomorrow'} availability`,`<form id="av-form" class="form-grid"><input type="hidden" name="date" value="${date}"><div class="field"><label>From</label><input class="input" type="time" name="fromTime" value="${from}"></div><div class="field"><label>To</label><input class="input" type="time" name="toTime" value="${to}"></div><div class="field wide"><label>Status</label><select class="select" name="online"><option value="true" ${online?'selected':''}>Online</option><option value="false" ${!online?'selected':''}>Offline</option></select></div></form>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveAvailability()">Save</button>`);
window.saveAvailability=async()=>{const f=new FormData($('#av-form'));try{await api('/api/cleaner/availability',{method:'PATCH',body:{date:f.get('date'),online:f.get('online')==='true',fromTime:f.get('fromTime'),toTime:f.get('toTime')}});closeModal();toast('Availability updated','success');render()}catch(e){toast(e.message,'error')}};
function miniDay(jobs){return jobs.length?`<div class="myday-line">${jobs.map(j=>`<div class="day-job ${j.status==='COMPLETED'?'done':['CLEANING','ARRIVED','EN_ROUTE'].includes(j.status)?'active':''}" onclick="navTo('cleaner/job/${j.id}')"><div style="display:flex;justify-content:space-between"><strong>${esc(j.object_code)}</strong>${statusPill(j.status)}</div><div class="address">${esc(j.zone)} · ${esc(j.projected_start||j.planned_start)}–${esc(j.projected_finish||j.eta||'—')}</div></div>`).join('')}</div>`:'<div class="job-card"><div class="empty">No jobs accepted yet.</div></div>'}

async function cleanerJobs(){const date=state.marketDate||today();const [d,m]=await Promise.all([cleanerHeaderAvailability(date),api(`/api/cleaner/marketplace?date=${date}`)]);const dayName=date===today()?'Today':'Tomorrow';const bundles=m.bundles||[];$('#page').innerHTML=`<div class="toolbar" style="margin-bottom:12px"><button class="btn sm ${date===today()?'primary':''}" onclick="setCleanerMarketDate('${today()}')">Today</button><button class="btn sm ${date===tomorrow()?'primary':''}" onclick="setCleanerMarketDate('${tomorrow()}')">Tomorrow</button><button class="btn sm" style="margin-left:auto" onclick="editAvailability('${d.availability.fromTime}','${d.availability.toTime}',${d.availability.online},'${date}')">${dayName} availability</button></div>${!d.availability.online?`<div class="job-card" style="border-color:#ffe0ad;background:#fffaf2"><strong>You are offline for ${dayName.toLowerCase()}</strong><p class="subtle">Set availability to show Operations that you can work this date. You can still inspect published jobs.</p></div>`:''}<div class="section-head"><div><h2>${dayName} marketplace</h2><p>Jobs matched to your availability and property deadlines.</p></div><span class="pill green">${m.jobs.filter(x=>x.feasible).length} feasible</span></div>${bundles.length?`<div class="eyebrow" style="margin:12px 3px 7px">Smart routes</div>${bundles.map(b=>`<div class="job-card bundle"><div class="head"><div><h3>${esc(b.zone)} route · ${b.count} jobs</h3><div class="address">Projected finish ${b.projectedFinish}</div></div><div class="price">${money(b.payout)}</div></div><div class="job-meta">${b.jobs.map(x=>`<span class="meta-chip">#${x.id}</span>`).join('')}</div><button class="btn blue full" onclick="takeBundle('${b.jobIds.join(',')}','${date}')">Take route</button></div>`).join('')}`:''}<div class="eyebrow" style="margin:16px 3px 7px">Available jobs</div>${m.jobs.map(j=>`<div class="job-card"><div class="head"><div><h3>${esc(j.object_code)} · ${esc(j.zone)}</h3><div class="address">${esc(j.address)}</div></div><div style="text-align:right"><div class="price">${money(Number(j.payout)+Number(j.bonus))}</div>${j.bonus?`<div class="bonus">Urgent +${money(j.bonus)}</div>`:''}</div></div><div class="job-meta"><span class="meta-chip">${j.duration_minutes} min</span><span class="meta-chip">Plan ${esc(j.planned_start||'10:00')}</span><span class="meta-chip">Finish ${esc(j.projected_finish||'—')}</span>${riskPill(j.risk_level,j.risk_score)}</div>${j.feasible?`<button class="btn primary full" onclick="acceptJob(${j.id},'${date}')">Take cleaning</button>`:`<button class="btn full" disabled>${esc(j.feasibility_reason||'Not feasible')}</button>`}</div>`).join('')||'<div class="job-card"><div class="empty">No marketplace jobs available.</div></div>'}`}
window.setCleanerMarketDate=date=>{state.marketDate=date;render()};
window.acceptJob=async(id,date=today())=>{try{await api(`/api/cleaner/jobs/${id}/accept`,{method:'POST',body:{}});state.myDayDate=date;toast('Cleaning added to My Day','success');render()}catch(e){toast(e.message,'error')}};
window.takeBundle=async(ids,date=today())=>{for(const id of String(ids).split(',').map(Number)){try{await api(`/api/cleaner/jobs/${id}/accept`,{method:'POST',body:{}})}catch(e){toast(`Route stopped: ${e.message}`,'error');return}}state.myDayDate=date;toast('Route accepted','success');navTo('cleaner/myday')};

async function cleanerMyDay(){const date=state.myDayDate||today();const d=await cleanerHeaderAvailability(date);const dayName=date===today()?'Today':'Tomorrow';$('#page').innerHTML=`<div class="toolbar" style="margin-bottom:12px"><button class="btn sm ${date===today()?'primary':''}" onclick="setMyDayDate('${today()}')">Today</button><button class="btn sm ${date===tomorrow()?'primary':''}" onclick="setMyDayDate('${tomorrow()}')">Tomorrow</button></div><div class="section-head"><div><h2>${dayName} · My Day</h2><p>Projected finish ${esc(d.projectedFinish)} · hard deadline 15:00</p></div></div>${miniDay(d.jobs)}<div class="job-card"><div class="detail-grid"><div class="detail-item"><div class="k">Jobs</div><div class="v">${d.total}</div></div><div class="detail-item"><div class="k">Earned completed</div><div class="v">${money(d.earnings)}</div></div></div></div>`}
window.setMyDayDate=date=>{state.myDayDate=date;cleanerMyDay()};
async function cleanerEarnings(){await cleanerHeaderAvailability();const d=await api('/api/cleaner/earnings');$('#page').innerHTML=`<div class="mobile-kpis"><div class="mobile-kpi" style="grid-column:span 2"><div class="v">${money(d.today)}</div><div class="k">TODAY</div></div><div class="mobile-kpi"><div class="v">${d.jobs.length}</div><div class="k">COMPLETED</div></div></div><div class="section-head" style="margin-top:18px"><div><h2>Completed cleanings</h2><p>Base payout + rescue / surge bonus</p></div></div>${d.jobs.map(j=>`<div class="job-card"><div class="head"><div><h3>${esc(j.object_code)} · ${esc(j.object_name)}</h3><div class="address">${fmtDate(j.service_date)} · ${esc(j.zone)}</div></div><div style="text-align:right"><div class="price">${money(Number(j.payout)+Number(j.bonus))}</div>${j.bonus?`<div class="bonus">+${money(j.bonus)} bonus</div>`:''}</div></div></div>`).join('')||'<div class="job-card"><div class="empty">No completed jobs yet.</div></div>'}`}
async function cleanerProfile(){const d=await cleanerHeaderAvailability();$('#page').innerHTML=`<div class="job-card"><div style="display:flex;align-items:center;gap:12px"><div class="avatar" style="width:52px;height:52px;font-size:17px">${initials(state.me.full_name)}</div><div><h2 style="margin:0">${esc(state.me.full_name)}</h2><div class="address">${esc(state.me.email)}</div></div></div><div class="detail-grid" style="margin-top:15px"><div class="detail-item"><div class="k">Mode</div><div class="v">${esc(state.me.cleaner_mode)}</div></div><div class="detail-item"><div class="k">Reliability</div><div class="v">${Math.round(state.me.reliability_score||0)}/100</div></div><div class="detail-item"><div class="k">Rating</div><div class="v">★ ${state.me.rating||'—'}</div></div><div class="detail-item"><div class="k">Transport</div><div class="v">${esc(state.me.transport||'—')}</div></div><div class="detail-item wide"><div class="k">Preferred zones</div><div class="v">${(state.me.preferred_zones||[]).map(x=>`<span class="pill gray">${esc(x)}</span>`).join(' ')||'—'}</div></div></div></div><div class="job-card"><strong>Availability today</strong><p class="subtle">${d.availability.fromTime}–${d.availability.toTime} · ${d.availability.online?'ONLINE':'OFFLINE'}</p><button class="btn full" onclick="editAvailability('${d.availability.fromTime}','${d.availability.toTime}',${d.availability.online})">Edit availability</button></div><div class="job-card"><strong>Account security</strong><p class="subtle">Use a personal password instead of the initial password sent by operations.</p><button class="btn full" onclick="passwordModal()">Change password</button></div><button class="btn red full" onclick="logout()">Sign out</button>`}
async function cleanerMap(){const [d,m]=await Promise.all([cleanerHeaderAvailability(),api('/api/cleaner/marketplace')]);const points=[...d.jobs.map(j=>({lat:j.lat,lng:j.lng,name:`${j.object_code} · ${j.status}`,detail:j.address,id:j.id,assigned:true})),...m.jobs.map(j=>({lat:j.lat,lng:j.lng,name:`${j.object_code} · available`,detail:`${j.zone} · ${money(Number(j.payout)+Number(j.bonus))}`,id:j.id,assigned:false}))];$('#page').innerHTML=`<div id="cleaner-map" class="map compact"></div><div style="height:10px"></div><div class="job-card"><strong>Map legend</strong><p class="subtle">Assigned jobs include full address. Marketplace access instructions remain hidden until you take the cleaning.</p></div>`;setTimeout(()=>renderLeaflet('cleaner-map',points,p=>p.assigned?navTo(`cleaner/job/${p.id}`):null),20)}

async function cleanerJobDetail(id){await cleanerHeaderAvailability();const j=await api(`/api/cleaner/jobs/${id}`);const required=j.checklist.filter(x=>x.required).length,done=j.checklist.filter(x=>x.required&&x.completed).length;const requiredCats=[...new Set(j.checklist.filter(x=>x.photo_required).map(x=>x.photo_category))];const photoCats=new Set(j.photos.filter(x=>x.mime?.startsWith('image/')).map(x=>x.category));$('#page').className='';$('#page').innerHTML=`<div class="active-job-head"><button class="back" onclick="navTo('cleaner/myday')">← My Day</button><h2>${esc(j.object_code)} · ${esc(j.object_name)}</h2><div class="address" style="color:#b7c0cf">${esc(j.address)}</div><div class="job-meta">${statusPill(j.status)} ${riskPill(j.risk_level,j.risk_score)} <span class="meta-chip">${money(Number(j.payout)+Number(j.bonus))}</span><span class="meta-chip">Deadline ${esc(j.deadline)}</span></div></div><div class="active-job-body"><div class="instruction"><h4>Access</h4><p>${esc(j.access_instructions||'No instructions')}</p></div><div class="detail-grid" style="margin-bottom:10px"><div class="detail-item"><div class="k">Key</div><div class="v">${esc(j.key_instructions||'—')}</div></div><div class="detail-item"><div class="k">Parking</div><div class="v">${esc(j.parking||'—')}</div></div><div class="detail-item"><div class="k">Linen</div><div class="v">${esc(j.linen_location||'—')}</div></div><div class="detail-item"><div class="k">Supplies</div><div class="v">${esc(j.supplies_location||'—')}</div></div></div><div class="instruction"><div style="display:flex;justify-content:space-between;align-items:center"><h4 style="margin:0">Cleaning checklist</h4><strong>${done}/${required}</strong></div><div class="meter" style="margin:10px 0 3px"><span style="width:${required?done/required*100:100}%"></span></div>${j.checklist.map(i=>`<div class="check-item"><button class="check-btn ${i.completed?'done':''}" onclick="toggleCheck(${j.id},${i.id},${!i.completed})">${i.completed?'✓':''}</button><span>${esc(i.label)}${i.required?' <span class="subtle">*</span>':''}</span>${i.photo_required?`<span class="photo-tag">📷 ${esc(i.photo_category)}</span>`:''}</div>`).join('')}</div><div class="instruction"><h4>Required photo proof</h4><div class="photo-grid">${requiredCats.map(c=>{const ph=j.photos.find(p=>p.category===c&&p.mime?.startsWith('image/'));return `<label class="photo-slot ${ph?'done':''}" style="${ph?'padding:0;overflow:hidden;display:block':''}">${ph?`<img src="${esc(ph.url)}" alt="${esc(c)}" style="width:100%;height:82px;object-fit:cover;display:block"><span style="display:block;padding:5px">✓ ${esc(c)}</span>`:`<span>＋<br>${esc(c)}</span><input hidden type="file" accept="image/*" onchange="uploadProof(${j.id},${esc(JSON.stringify(c))},this)">`}</label>`}).join('')}</div></div><div class="instruction"><h4>Additional report</h4><div class="photo-grid">${j.photos.filter(p=>p.category==='Additional').map(p=>proofMedia(p)).join('')}</div>${!['COMPLETED','CANCELLED'].includes(j.status)?`<label class="btn">Add photo or video<input hidden type="file" accept="image/*,video/mp4,video/webm" onchange="uploadProof(${j.id},'Additional',this)"></label>`:''}</div>${j.issues.length?`<div class="instruction"><h4>Issues</h4>${j.issues.map(i=>`<div class="risk-row ${i.status==='OPEN'?'orange':''}"><div class="risk-score" style="width:36px;height:36px">!</div><div><strong>${esc(i.type)}</strong><small>${esc(i.description||'')} · ${esc(i.status)}</small></div></div>`).join('')}</div>`:''}<div class="instruction"><h4>Notes</h4><p>${esc(j.object_notes||'No special notes.')}</p></div></div><div class="sticky-action">${jobActionButtons(j,done,required,requiredCats,photoCats)}</div>`}
function jobActionButtons(j,done,required,requiredCats,photoCats){const completeReady=done===required&&requiredCats.every(x=>photoCats.has(x));if(j.status==='COMPLETED')return `<button class="btn green full" disabled>✓ Completed</button>`;if(j.status==='ACCEPTED')return `<button class="btn red" onclick="cancelCleanerJob(${j.id})">Can't do</button><button class="btn" onclick="reportIssue(${j.id})">Issue</button><button class="btn primary" onclick="jobStatus(${j.id},'EN_ROUTE')">I'm on my way</button>`;if(j.status==='EN_ROUTE')return `<button class="btn" onclick="reportIssue(${j.id})">Issue</button><button class="btn primary" onclick="checkInJob(${j.id})">Arrived / Check in</button>`;if(j.status==='ARRIVED')return `<button class="btn" onclick="reportIssue(${j.id})">Issue</button><button class="btn primary" onclick="jobStatus(${j.id},'CLEANING')">Start cleaning</button>`;return `<button class="btn" onclick="reportIssue(${j.id})">Issue</button><button class="btn green" ${completeReady?'':'disabled'} onclick="completeJob(${j.id})">Complete cleaning</button>`}
window.cancelCleanerJob=async id=>{const reason=prompt('Why can’t you do this cleaning? Operations will be notified.','');if(reason===null)return;if(!reason.trim())return toast('Reason is required','error');if(!confirm('Release this cleaning back to Operations?'))return;try{const d=await api(`/api/cleaner/jobs/${id}/cancel`,{method:'POST',body:{reason:reason.trim()}});toast(d.rescue?'Late cancellation: Rescue opened':'Cleaning released','success');navTo('cleaner/myday')}catch(e){toast(e.message,'error')}};
window.jobStatus=async(id,status)=>{try{await api(`/api/cleaner/jobs/${id}/status`,{method:'POST',body:{status}});toast(`Status: ${status}`,'success');await render()}catch(e){toast(e.message,'error')}};
window.checkInJob=id=>{if(navigator.geolocation)navigator.geolocation.getCurrentPosition(async pos=>{try{const d=await api(`/api/cleaner/jobs/${id}/status`,{method:'POST',body:{status:'ARRIVED',lat:pos.coords.latitude,lng:pos.coords.longitude}});toast(d.warning||'Checked in',d.warning?'error':'success');await render()}catch(e){toast(e.message,'error')}},()=>jobStatus(id,'ARRIVED'),{enableHighAccuracy:true,timeout:6000});else jobStatus(id,'ARRIVED')};
window.toggleCheck=async(jobId,itemId,completed)=>{try{await api(`/api/cleaner/jobs/${jobId}/checklist/${itemId}`,{method:'PATCH',body:{completed}});await render()}catch(e){toast(e.message,'error')}};
window.uploadProof=async(jobId,category,input)=>{const file=input.files?.[0];if(!file||state.uploading)return;state.uploading=true;input.disabled=true;try{let prepared=file;if(!file.type.startsWith('video/')){const data=await compressProof(file);const blob=await (await fetch(data)).blob();prepared=new File([blob],(file.name||'photo').replace(/\.[^.]+$/,'')+'.jpg',{type:'image/jpeg'})}else if(!['video/mp4','video/webm'].includes(file.type)||file.size>50*1024*1024)throw new Error('Video must be MP4 or WebM under 50 MB');await window.ShineTimeSupabase.uploadProofFile(jobId,category,prepared,stage=>toast(t(stage,stage),'info'));toast(`${category} uploaded`,'success');state.uploading=false;await render()}catch(e){toast(e.message||'Photo upload failed','error')}finally{state.uploading=false;input.disabled=false}};async function compressProof(file){if(file.size>12*1024*1024)throw new Error('Photo must be under 12 MB');const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(new Error('Cannot read photo'));i.src=url});const max=1600,scale=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight)),w=Math.max(1,Math.round(img.naturalWidth*scale)),h=Math.max(1,Math.round(img.naturalHeight*scale));const c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d');ctx.drawImage(img,0,0,w,h);return c.toDataURL('image/jpeg',.82)}finally{URL.revokeObjectURL(url)}}
window.reportIssue=id=>modal('Report issue',`<form id="issue-form" class="form-grid"><div class="field wide"><label>Type</label><select class="select" name="type">${['Damage','Missing linen','Guest still inside','Extreme dirt','Missing key','Maintenance','Missing supplies','Other'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field wide"><label>Description</label><textarea class="textarea" name="description" placeholder="What happened?"></textarea></div></form>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn red" onclick="submitIssue(${id})">Send issue</button>`);
window.submitIssue=async id=>{const f=new FormData($('#issue-form'));try{await api(`/api/cleaner/jobs/${id}/issues`,{method:'POST',body:{type:f.get('type'),description:f.get('description')}});closeModal();toast('Operations notified','success');await render()}catch(e){toast(e.message,'error')}};
window.completeJob=async id=>{try{await api(`/api/cleaner/jobs/${id}/complete`,{method:'POST',body:{}});toast('Cleaning completed','success');navTo('cleaner/myday')}catch(e){if(e.data?.missingPhotos?.length)toast(`Missing photos: ${e.data.missingPhotos.join(', ')}`,'error');else toast(e.message,'error')}};


async function renderClient(page){
    if(page==='home')return clientHome();
    if(page==='book')return clientBook();
    if(page==='objects')return clientObjects();
    if(page==='bookings')return clientBookings();
    if(page==='finance'){
      if(state.me.role!=='OWNER'){navTo('client/home');return clientHome();}
      return clientFinance();
    }
    if(page==='profile')return clientProfile();
    return clientHome();
}

async function clientHome(){const d=await api('/api/client/dashboard');$('#page').innerHTML=`<div class="client-welcome"><span class="eyebrow">Shine Time</span><h2>${esc(state.me.company_name||state.me.full_name)}</h2><p>Your team. Every job. In sync.</p></div><div class="mobile-kpis"><div class="job-card mini"><span>Objects</span><strong>${d.objects.total}</strong><small>${d.objects.approved} Approved</small></div><div class="job-card mini"><span>Pending approval</span><strong>${d.objects.pending}</strong><small>Awaiting Operations</small></div><div class="job-card mini"><span>Upcoming cleanings</span><strong>${d.upcoming.length}</strong><small>${d.completedToday} Completed today</small></div></div>${d.nextBooking?`<div class="section-head client-section"><div><h2>Next cleaning</h2><p>${fmtDate(d.nextBooking.service_date)}</p></div></div><button class="job-card client-next" onclick="navTo('client/booking/${d.nextBooking.id}')"><div class="job-card-top"><div><strong>${esc(d.nextBooking.object_code)} · ${esc(d.nextBooking.object_name)}</strong><span>${esc(d.nextBooking.address)}</span></div>${statusPill(d.nextBooking.status)}</div><div class="route-line"><span>${esc(d.nextBooking.planned_start||d.nextBooking.earliest_start)} → ${esc(d.nextBooking.deadline)}</span><strong>${money(Number(d.nextBooking.client_price)+Number(d.nextBooking.extra_revenue||0))}</strong></div></button>`:`<div class="job-card"><strong>No upcoming cleanings.</strong><p class="subtle">Reserve your next cleaning when you are ready.</p><button class="btn primary full" onclick="navTo('client/book')">Book Cleaning</button></div>`}<div class="section-head client-section"><div><h2>Upcoming cleanings</h2></div><button class="btn sm" onclick="navTo('client/bookings')">Open</button></div>${d.upcoming.slice(0,5).map(b=>`<button class="job-card compact-card" onclick="navTo('client/booking/${b.id}')"><div><strong>${fmtDate(b.service_date)} · ${esc(b.object_code)}</strong><span>${esc(b.planned_start||b.earliest_start)} · ${esc(b.address)}</span></div>${statusPill(b.status)}</button>`).join('')||'<div class="job-card"><span class="subtle">No bookings yet.</span></div>'}`}

async function clientObjects(){const d=await api('/api/client/objects');state.clientObjects=d.objects;$('#page').innerHTML=`<div class="section-head client-section"><div><h2>My properties</h2><p>Add a property and wait for Operations approval before booking.</p></div><button class="btn primary" onclick="clientObjectModal()">+ Add property</button></div>${d.objects.map(o=>`<div class="job-card"><div class="job-card-top"><div><strong>${esc(o.code)} · ${esc(o.name)}</strong><span>${esc(o.address)} · ${esc(o.zone)}</span></div>${o.approval_status==='APPROVED'&&o.active?'<span class="pill green">Approved</span>':o.approval_status==='PENDING'?'<span class="pill orange">Pending approval</span>':'<span class="pill gray">'+esc(o.approval_status)+'</span>'}</div><div class="detail-grid" style="margin-top:10px"><div class="detail-item"><div class="k">Type</div><div class="v">${esc(o.apartment_type)}</div></div><div class="detail-item"><div class="k">Price per cleaning</div><div class="v">${Number(o.client_price)>0?money(o.client_price):'—'}</div></div></div><div class="job-actions"><button class="btn sm" onclick="clientObjectModal(${o.id})">Edit</button>${o.approval_status==='APPROVED'&&o.active?`<button class="btn primary sm" onclick="navTo('client/book?object=${o.id}')">Book Cleaning</button>`:''}</div></div>`).join('')||'<div class="job-card"><div class="empty">No properties yet.</div></div>'}`}

window.clientObjectModal=async id=>{try{const o=id?(await api(`/api/client/objects/${id}`)).object:{};modal(id?'Edit property':'Add property',`<form id="client-object-form" class="form-grid"><div class="field"><label>Name</label><input class="input" name="name" required value="${esc(o.name||'')}"></div>${id?`<div class="field"><label>Code</label><input class="input" value="${esc(o.code||'')}" disabled></div>`:''}<div class="field wide"><label>Address</label><input class="input" name="address" required value="${esc(o.address||'')}"></div><div class="field"><label>Zone</label><input class="input" name="zone" required value="${esc(o.zone||'')}"></div><div class="field"><label>Apartment type</label><input class="input" name="apartmentType" value="${esc(o.apartment_type||'Apartment')}"></div><div class="field"><label>Bedrooms</label><input class="input" type="number" min="0" name="bedrooms" value="${o.bedrooms??1}"></div><div class="field"><label>Bathrooms</label><input class="input" type="number" min="1" name="bathrooms" value="${o.bathrooms??1}"></div><div class="field"><label>Latitude</label><input class="input" name="lat" type="text" inputmode="decimal" autocomplete="off" placeholder="48.177333" value="${o.lat??''}"></div><div class="field"><label>Longitude</label><input class="input" name="lng" type="text" inputmode="decimal" autocomplete="off" placeholder="17.126286" value="${o.lng??''}"></div><div class="field wide"><label>Access instructions</label><textarea class="textarea" name="accessInstructions">${esc(o.access_instructions||'')}</textarea></div><div class="field"><label>Key instructions</label><textarea class="textarea" name="keyInstructions">${esc(o.key_instructions||'')}</textarea></div><div class="field"><label>Parking</label><textarea class="textarea" name="parking">${esc(o.parking||'')}</textarea></div><div class="field"><label>Linen location</label><input class="input" name="linenLocation" value="${esc(o.linen_location||'')}"></div><div class="field"><label>Supplies location</label><input class="input" name="suppliesLocation" value="${esc(o.supplies_location||'')}"></div><div class="field wide"><label>Notes</label><textarea class="textarea" name="notes">${esc(o.notes||'')}</textarea></div>${id&&o.approval_status==='APPROVED'?'<div class="wide notice-inline">Changing the address or basic property parameters sends the object back to Operations for approval.</div>':''}</form>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveClientObject(${id||0})">Save</button>`)}catch(e){toast(e.message,'error')}};
window.saveClientObject=async id=>{const f=new FormData($('#client-object-form'));let coordinates;try{coordinates=coordinatesFrom(f)}catch(e){return toast(e.message,'error')}const body={name:f.get('name'),address:f.get('address'),zone:f.get('zone'),serviceCategory:f.get('serviceCategory')||'SHORT_STAY',apartmentType:f.get('apartmentType'),bedrooms:Number(f.get('bedrooms')),bathrooms:Number(f.get('bathrooms')),lat:coordinates.lat,lng:coordinates.lng,accessInstructions:f.get('accessInstructions'),keyInstructions:f.get('keyInstructions'),parking:f.get('parking'),linenLocation:f.get('linenLocation'),suppliesLocation:f.get('suppliesLocation'),notes:f.get('notes')};try{await api(id?`/api/client/objects/${id}`:'/api/client/objects',{method:id?'PATCH':'POST',body});closeModal();toast('Object saved','success');clientObjects()}catch(e){toast(e.message,'error')}};

async function clientBook(){const d=await api('/api/client/objects');const objects=d.objects.filter(o=>o.approval_status==='APPROVED'&&o.active);const query=new URLSearchParams(location.hash.split('?')[1]||'');const selected=Number(query.get('object')||objects[0]?.id||0);$('#page').innerHTML=`<div class="section-head client-section"><div><h2>Reserve a cleaning</h2><p>Choose property, date and one of the available cleaning slots.</p></div></div>${objects.length?`<div class="job-card"><form id="client-book-form" class="form-grid"><div class="field wide"><label>Property</label><select class="select" name="objectId" onchange="loadClientSlots()">${objects.map(o=>`<option value="${o.id}" ${o.id===selected?'selected':''}>${esc(o.code)} · ${esc(o.name)} · ${Number(o.client_price)>0?money(o.client_price):'price by agreement'}</option>`).join('')}</select></div><div class="field wide"><label>Date</label><input class="input" type="date" name="serviceDate" min="${today()}" value="${tomorrow()}" onchange="loadClientSlots()"></div></form><div id="client-slots"><div class="empty">Loading…</div></div></div>`:`<div class="job-card"><strong>No approved properties.</strong><p class="subtle">Object is awaiting approval.</p><button class="btn" onclick="navTo('client/objects')">Objects</button></div>`}`;if(objects.length)loadClientSlots()}
window.loadClientSlots=async()=>{const f=$('#client-book-form');if(!f)return;const objectId=Number(f.objectId.value),date=f.serviceDate.value;const box=$('#client-slots');box.innerHTML='<div class="empty">Loading…</div>';try{const d=await api(`/api/client/slots?objectId=${objectId}&date=${date}`);box.innerHTML=`<div class="client-price-row"><span>${esc(d.object.name)}</span><strong>${Number(d.object.client_price)>0?money(d.object.client_price):'—'}</strong></div><h4>Available slots</h4>${d.slots.length?`<div class="slot-grid">${d.slots.map(s=>`<button class="slot-btn" onclick="selectClientSlot(this,'${s}')">${s}</button>`).join('')}</div><button id="reserve-cleaning-btn" class="btn primary full" disabled onclick="reserveClientCleaning()">Reserve cleaning</button>`:'<div class="empty">No available slots for this date.</div>'}<input id="selected-client-slot" type="hidden">`}catch(e){box.innerHTML=`<div class="empty error-text">${esc(e.message)}</div>`}};
window.selectClientSlot=(el,slot)=>{$$('.slot-btn').forEach(x=>x.classList.remove('active'));el.classList.add('active');$('#selected-client-slot').value=slot;$('#reserve-cleaning-btn').disabled=false};
window.reserveClientCleaning=async()=>{const f=$('#client-book-form'),slot=$('#selected-client-slot')?.value;if(!slot)return toast('Choose a cleaning slot','error');try{const d=await api('/api/client/bookings',{method:'POST',body:{objectId:Number(f.objectId.value),serviceDate:f.serviceDate.value,startTime:slot}});toast('Reservation created','success');navTo(`client/booking/${d.booking.id}`)}catch(e){toast(e.message,'error');loadClientSlots()}};

async function clientBookings(){const d=await api('/api/client/bookings');const rows=d.bookings;$('#page').innerHTML=`<div class="section-head client-section"><div><h2>Booking history</h2><p>${rows.length} bookings</p></div><button class="btn primary" onclick="navTo('client/book')">Book Cleaning</button></div><div class="booking-list">${rows.map(b=>`<button class="job-card compact-card" onclick="navTo('client/booking/${b.id}')"><div><strong>${fmtDate(b.service_date)} · ${esc(b.object_code)} · ${esc(b.object_name)}</strong><span>${esc(b.planned_start||b.earliest_start)} · ${esc(b.address)}</span><small>${money(Number(b.client_price)+Number(b.extra_revenue||0))}</small></div>${statusPill(b.status)}</button>`).join('')||'<div class="job-card"><div class="empty">No bookings yet.</div></div>'}</div>`}

async function clientBookingDetail(id){try{const d=await api(`/api/client/bookings/${id}`),j=d.booking;$('#page').innerHTML=`<div class="active-job-head client-detail-head"><button class="back" onclick="navTo('client/bookings')">← Bookings</button><h2>${esc(j.object_code)} · ${esc(j.object_name)}</h2><div class="address" style="color:#b7c0cf">${esc(j.address)}</div><div class="job-meta">${statusPill(j.status)} <span class="meta-chip">${fmtDate(j.service_date)}</span><span class="meta-chip">${esc(j.planned_start||j.earliest_start)}–${esc(j.deadline)}</span><span class="meta-chip">${money(Number(j.client_price)+Number(j.extra_revenue||0))}</span></div></div><div class="active-job-body"><div class="instruction"><h4>Cleaning</h4><div class="detail-grid"><div class="detail-item"><div class="k">Status</div><div class="v">${statusPill(j.status)}</div></div><div class="detail-item"><div class="k">ETA</div><div class="v">${esc(j.eta||'—')}</div></div><div class="detail-item"><div class="k">Price</div><div class="v">${money(Number(j.client_price)+Number(j.extra_revenue||0))}</div></div><div class="detail-item"><div class="k">Financial status</div><div class="v">${esc(j.financial_status||'PENDING')}</div></div></div></div>${d.photos.length?`<div class="instruction"><h4>Proof photos</h4><div class="photo-grid">${d.photos.map(p=>proofMedia(p)).join('')}</div></div>`:''}${d.issues.length?`<div class="instruction"><h4>Issues</h4>${d.issues.map(i=>`<div class="risk-row"><div class="risk-score">!</div><div><strong>${esc(i.type)}</strong><small>${esc(i.description||'')} · ${esc(i.status)}</small></div></div>`).join('')}</div>`:''}</div>${!['COMPLETED','CANCELLED'].includes(j.status)&&j.service_date>=today()?`<div class="sticky-action"><button class="btn red full" onclick="cancelClientBooking(${j.id})">Cancel booking</button></div>`:''}`;}catch(e){$('#page').innerHTML=`<div class="job-card"><strong>${esc(e.message)}</strong><button class="btn full" onclick="navTo('client/bookings')">Back</button></div>`}}
async function clientFinance(){
  const month=state.clientFinanceMonth||new Date().toISOString().slice(0,7);
  const data=await api('/api/client/finance?month='+encodeURIComponent(month));
  const summary=data.summary||{};
  const points=Array.isArray(data.trend)?data.trend:[];
  const scale=Math.max(1,...points.flatMap(point=>[Number(point.revenue||0),Number(point.expenses||0)]));
  const trend=points.map(point=>{
    const revenue=Math.max(3,Math.round(Number(point.revenue||0)/scale*100));
    const expenses=Math.max(3,Math.round(Number(point.expenses||0)/scale*100));
    return '<div class="trend-col"><div class="trend-bars" title="'+esc(point.month)+'"><span class="trend-revenue" style="height:'+revenue+'%"></span><span class="trend-expense" style="height:'+expenses+'%"></span></div><strong>'+esc(point.month.slice(5))+'</strong><small>'+money(point.profit)+'</small></div>';
  }).join('')||'<div class="empty">No portfolio activity for this period.</div>';
  const objectRows=(data.byObject||[]).map(row=>'<tr><td><strong>'+esc(row.code||'—')+'</strong><br><span class="subtle">'+esc(row.name||'Unnamed property')+'</span></td><td>'+Number(row.jobs||0)+'</td><td>'+money(row.revenue)+'</td><td>'+money(row.cost)+'</td><td class="'+(Number(row.profit||0)>=0?'profit-pos':'profit-neg')+'">'+money(row.profit)+'</td></tr>').join('')||'<tr><td colspan="5" class="empty">No completed cleanings in this month.</td></tr>';
  const entries=(data.entries||[]).map(entry=>'<div class="risk-row"><div class="risk-score" style="background:'+(entry.entry_type==='INCOME'?'#e9f7f0':'#ffeaec')+';color:'+(entry.entry_type==='INCOME'?'#087b4d':'#b52634')+'">'+(entry.entry_type==='INCOME'?'+':'−')+'</div><div><strong>'+esc(entry.category||entry.entry_type)+'</strong><small>'+fmtDate(entry.entry_date)+' · '+esc(entry.object_code||'Portfolio')+(entry.description?' · '+esc(entry.description):'')+'</small></div><strong class="'+(entry.entry_type==='INCOME'?'profit-pos':'profit-neg')+'">'+(entry.entry_type==='INCOME'?'+':'−')+money(entry.amount)+'</strong></div>').join('')||'<div class="empty">No additional financial entries for this month.</div>';
  $('#page').innerHTML='<div class="section-head client-section"><div><h2>Portfolio finance</h2><p>Completed cleanings, operating costs and profitability.</p></div><input class="input" type="month" value="'+esc(data.month||month)+'" onchange="setClientFinanceMonth(this.value)" style="width:auto"></div><div class="mobile-kpis" style="grid-template-columns:repeat(3,1fr)"><div class="job-card mini"><span>Revenue</span><strong>'+money(summary.totalRevenue)+'</strong><small>'+Number(summary.completedJobs||0)+' completed cleanings</small></div><div class="job-card mini"><span>Costs</span><strong>'+money(summary.totalExpenses)+'</strong><small>Cleaner payout and extras</small></div><div class="job-card mini"><span>Profit</span><strong class="'+(Number(summary.profit||0)>=0?'profit-pos':'profit-neg')+'">'+money(summary.profit)+'</strong><small>'+Number(summary.marginPct||0)+'% margin</small></div></div><div class="job-card"><div class="section-head compact"><div><h2>12-month trend</h2><p>Blue: revenue · orange: costs</p></div></div><div class="finance-trend">'+trend+'</div></div><div class="job-card"><div class="section-head compact"><div><h2>By property</h2><p>Only your portfolio and completed cleanings.</p></div></div><div class="table-wrap"><table><thead><tr><th>Property</th><th>Jobs</th><th>Revenue</th><th>Costs</th><th>Profit</th></tr></thead><tbody>'+objectRows+'</tbody></table></div></div><div class="job-card"><div class="section-head compact"><div><h2>Adjustments</h2><p>Income and expense entries tied to your portfolio.</p></div></div>'+entries+'</div>';
}
window.setClientFinanceMonth=month=>{if(!/^\d{4}-\d{2}$/.test(String(month||'')))return;state.clientFinanceMonth=month;clientFinance().catch(error=>toast(error.message,'error'));};

window.cancelClientBooking=async id=>{const reason=prompt('Cancellation reason:','');if(reason===null)return;if(!confirm('Cancel this cleaning reservation?'))return;try{await api(`/api/client/bookings/${id}/cancel`,{method:'POST',body:{reason}});toast('Booking cancelled','success');navTo('client/bookings')}catch(e){toast(e.message,'error')}};

async function clientProfile(){const d=await api('/api/client/profile'),c=d.client||{};$('#page').innerHTML=`<div class="section-head client-section"><div><h2>Client profile</h2><p>${esc(c.account_type||state.me.role)}</p></div></div><div class="job-card"><form id="client-profile-form" class="form-grid"><div class="field"><label>Full name</label><input class="input" name="fullName" value="${esc(c.full_name||state.me.full_name)}"></div><div class="field"><label>Login email</label><input class="input" type="email" value="${esc(c.email||state.me.email)}" readonly aria-readonly="true"><small class="subtle">To change the login email, contact Operations.</small></div><div class="field"><label>Phone</label><input class="input" name="phone" value="${esc(c.phone||state.me.phone||'')}"></div><div class="field"><label>Language</label><select class="select" name="language">${ST_I18N.LANGS.map(l=>`<option value="${l}" ${String(c.language||state.me.language||'ru')===l?'selected':''}>${ST_I18N.NAMES[l]}</option>`).join('')}</select></div><div class="field wide"><label>Company name</label><input class="input" name="companyName" value="${esc(c.company_name||'')}"></div><div class="field"><label>Billing name</label><input class="input" name="billingName" value="${esc(c.billing_name||'')}"></div><div class="field"><label>ICO</label><input class="input" name="ico" value="${esc(c.ico||'')}"></div><div class="field"><label>DIC</label><input class="input" name="dic" value="${esc(c.dic||'')}"></div><div class="field"><label>IC DPH</label><input class="input" name="icDph" value="${esc(c.ic_dph||'')}"></div><div class="field wide"><label>Billing address</label><input class="input" name="billingAddress" value="${esc(c.billing_address||'')}"></div><div class="wide"><button type="button" class="btn primary full" onclick="saveClientProfile()">Save profile</button></div></form><div style="height:14px;border-top:1px solid var(--line);margin-top:14px;padding-top:14px"><button class="btn full" onclick="passwordModal()">Change password</button><button class="btn ghost full" style="margin-top:8px" onclick="logout()">Sign out</button></div></div>`}
window.saveClientProfile=async()=>{const f=new FormData($('#client-profile-form'));try{const lang=f.get('language');await api('/api/client/profile',{method:'PATCH',body:{fullName:f.get('fullName'),phone:f.get('phone'),language:lang,companyName:f.get('companyName'),billingName:f.get('billingName'),ico:f.get('ico'),dic:f.get('dic'),icDph:f.get('icDph'),billingAddress:f.get('billingAddress')}});state.me.language=lang;state.locale=ST_I18N.setLocale(lang);toast('Profile saved','success');render()}catch(e){toast(e.message,'error')}};
const openClientObjectModal=window.clientObjectModal;
window.clientObjectModal=async id=>{if(!id&&state.me?.role!=='OWNER')return toast('Only the owner can add a property','error');return openClientObjectModal(id);};

window.passwordModal=()=>modal('Change password',`<form id="password-form" class="form-grid"><div class="field wide"><label>Current password</label><input class="input" type="password" name="currentPassword" required></div><div class="field wide"><label>New password</label><input class="input" type="password" name="newPassword" minlength="8" required></div><div class="field wide"><label>Repeat new password</label><input class="input" type="password" name="repeatPassword" minlength="8" required></div></form>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="savePassword()">Update password</button>`);window.savePassword=async()=>{const f=new FormData($('#password-form')),a=f.get('newPassword'),b=f.get('repeatPassword');if(a!==b)return toast('New passwords do not match','error');try{await api('/api/account/password',{method:'POST',body:{currentPassword:f.get('currentPassword'),newPassword:a}});closeModal();toast('Password changed','success')}catch(e){toast(e.message,'error')}};

window.forgotPassword=()=>modal(t('Reset password','Reset password'),`<form id="reset-password-form"><div class="field"><label>Email</label><input class="input" type="email" name="email" autocomplete="email" required></div><p class="subtle">${t('We will send you a secure recovery link.','We will send you a secure recovery link.')}</p></form>`,`<button class="btn" onclick="closeModal()">${t('Cancel','Cancel')}</button><button class="btn primary" onclick="sendResetPassword()">${t('Send link','Send link')}</button>`);
window.sendResetPassword=async()=>{const form=$('#reset-password-form');if(!form.reportValidity())return;try{await window.ShineTimeSupabase.resetPassword(form.email.value.trim());closeModal();toast(t('If the account exists, a recovery link will arrive shortly.','If the account exists, a recovery link will arrive shortly.'),'success')}catch(e){toast(e.message,'error')}};
window.recoveryModal=()=>modal(t('Set new password','Set new password'),`<form id="recovery-form"><div class="field"><label>${t('New password','New password')}</label><input class="input" name="password" type="password" autocomplete="new-password" minlength="12" required></div><div class="field"><label>${t('Repeat new password','Repeat new password')}</label><input class="input" name="repeat" type="password" autocomplete="new-password" minlength="12" required></div></form>`,`<button class="btn primary" onclick="finishRecovery()">${t('Save','Save')}</button>`);
window.finishRecovery=async()=>{const form=$('#recovery-form');if(!form.reportValidity())return;if(form.password.value!==form.repeat.value)return toast(t('New passwords do not match','New passwords do not match'),'error');try{await window.ShineTimeSupabase.recoverPassword(form.password.value);closeModal();toast(t('Password changed','Password changed'),'success');await bootstrap()}catch(e){toast(e.message,'error')}};

window.setFinancePeriod=month=>{state.financeMonth=month;state.financeCursor=null;render()};
window.financePage=cursor=>{state.financeCursor=cursor;render()};

function proofMedia(p){return p.mime?.startsWith('video/')?`<video controls preload="metadata" src="${esc(p.url)}" style="width:100%;max-height:240px"></video>`:`<a href="${esc(p.url)}" target="_blank" rel="noopener"><img src="${esc(p.url)}" alt="${esc(p.category)}" style="width:100%;height:105px;object-fit:cover"></a>`}
